final class GeneratedModifyingMouseTapsAreHandedBackAcrossASessionSwitchTests: XCTestCase {
    func testModifyingMouseTapsAreHandedBackAcrossASessionSwitch() {
        var checks = 0
        func expect(_ condition: Bool, _ message: @autoclosure () -> String) {
            checks += 1
            XCTAssertTrue(condition, message())
        }
        func expectEqual(_ actual: String, _ expected: String, _ label: String) {
